sealed partial class SoundCanvas {
 public RectangleF ImageCrop=new RectangleF(0,0,1,1);public Action<PointF> OpenComponentAt;public Action ImageCleared;
 public Bitmap SnapshotImage(){return backgroundImage==null?null:new Bitmap(backgroundImage);}
 protected override void OnMouseDoubleClick(MouseEventArgs e){base.OnMouseDoubleClick(e);if(OpenComponentAt!=null)OpenComponentAt(Position);}
}
sealed class VisionRegion {
 public double Left,Top,Right,Bottom;public string Label,Analogy,Source;
 public override string ToString(){return Label;}
}
sealed partial class FormasForm {
 readonly ComboBox visionEngine=new ComboBox(),visionRegions=new ComboBox();readonly CheckBox visionInterpretations=new CheckBox();readonly TextBox visionEndpoint=new TextBox(),visionModel=new TextBox(),visionKey=new TextBox();
 readonly List<VisionRegion> regions=new List<VisionRegion>();string visionOverview="Sin descripción semántica.",visionSource="Geometría extraída";bool visionFocused=false,visionBusy=false,visionApiPending=false;int visionRevision=0;
 void BuildVision(){var p=Page("Imagen inteligente");Paragraph(p,"Importa una imagen en Imagen. Aquí puedes escuchar una vista general, abrir componentes en primer plano y volver al conjunto. Las interpretaciones son hipótesis. Doble clic o Intro en el lienzo abre la región señalada; también puedes usar la lista y el botón Abrir componente.");
  Check(p,visionInterpretations,"Escuchar hipótesis y analogías",true,RefreshVisionLabels);Select(p,"Componente",visionRegions,new string[0],0,()=>{if(visionFocused)FocusVision(visionRegions.SelectedIndex);});visionRegions.DoubleClick+=(s,e)=>FocusVision(visionRegions.SelectedIndex);
  Button(p,"Vista general e interpretaciones",()=>{Stop();Speak((visionInterpretations.Checked?visionSource+". Interpretación aproximada: "+visionOverview+" ":"Interpretaciones ocultas. ")+regions.Count+" regiones explorables.");});
  Button(p,"Describir componente seleccionado",()=>{Stop();Speak(VisionDescription());});Button(p,"Abrir componente seleccionado en primer plano",()=>FocusVision(visionRegions.SelectedIndex));Button(p,"Volver al conjunto",RestoreVision);Button(p,"Corregir interpretación o analogía",CorrectVision);
  Select(p,"Motor de reconocimiento",visionEngine,new string[]{"Local compacto · SSD-MobileNet cuantizado","Local estándar · SSD-MobileNet","Gemini · API","API compatible · Chat Completions"},0,()=>{visionKey.Clear();visionEndpoint.Text=visionEngine.SelectedIndex==2?"https://generativelanguage.googleapis.com/v1beta":"https://api.openai.com/v1/chat/completions";});
  foreach(var item in new[]{new KeyValuePair<string,TextBox>("Dirección de API",visionEndpoint),new KeyValuePair<string,TextBox>("Modelo de visión habilitado en tu proveedor",visionModel),new KeyValuePair<string,TextBox>("Clave de API, sólo durante esta ejecución",visionKey)}){Paragraph(p,item.Key);item.Value.AccessibleName=item.Key;item.Value.Width=650;item.Value.MaxLength=2048;p.Controls.Add(item.Value);}visionKey.UseSystemPasswordChar=true;visionEndpoint.Text="https://generativelanguage.googleapis.com/v1beta";
  Paragraph(p,"Exploración por nodos: máximo seis objetos con confianza mínima del sesenta por ciento. Al entrar en una zona se anuncia su etiqueta. Los dos modelos locales no envían fotos. El botón de API transmite la imagen completa al destino indicado; requiere tu cuenta y puede tener coste. La clave no se guarda ni se exporta. La caja delimita una zona de exploración; no representa la silueta exacta.");
  Button(p,"Analizar con motor local elegido",RunLocalVision);Button(p,"Enviar esta imagen a la API elegida",RunVisionApi);Button(p,"Olvidar clave de API",()=>{visionKey.Clear();Say("Clave retirada de los controles.");});
  canvas.OpenComponentAt=OpenVisionAt;canvas.ImageCleared=()=>{visionRevision++;visionApiPending=false;regions.Clear();visionRegions.Items.Clear();visionFocused=false;visionOverview="Sin interpretación semántica disponible.";};
 }
 void ResetVisionForImage(){visionApiPending=false;visionRevision++;visionFocused=false;canvas.ImageCrop=new RectangleF(0,0,1,1);}
 void RunLocalVision(){if(visionEngine.SelectedIndex>=2){Say("Elige uno de los dos motores locales.");return;}if(visionBusy){Say("Hay un reconocimiento local en curso.");return;}Bitmap snapshot=canvas.SnapshotImage();if(snapshot==null){Say("Importa primero una imagen.");return;}Stop();int request=visionRevision;bool standard=visionEngine.SelectedIndex==1;visionBusy=true;Say("Reconociendo localmente; la imagen no sale del equipo…");Task.Run(()=>{string payload=null;try{payload=LocalVision.Analyze(snapshot,Path.Combine(home,"vision"),standard);}catch{}finally{snapshot.Dispose();}if(closing)return;try{BeginInvoke((Action)(()=>{visionBusy=false;if(request!=visionRevision){if(canvas.HasBackground&&visionEngine.SelectedIndex<2)RunLocalVision();return;}if(payload==null){Say("No se pudo ejecutar el motor local. Prueba el otro; puedes volver a analizar la captura.");return;}visionFocused=false;canvas.ImageCrop=new RectangleF(0,0,1,1);Send("VISION_DATA|"+B64(payload));Log(standard?"vision_local_standard":"vision_local_compact");}));}catch{}});}
 void RunVisionApi(){if(visionApiPending){Say("Hay una consulta de API en curso.");return;}if(visionEngine.SelectedIndex<2){Say("Elige Gemini o API compatible antes de enviar.");return;}if(!canvas.HasBackground){Say("Importa primero una imagen.");return;}if(visionBusy){Say("Espera a que termine el reconocimiento local.");return;}if(visionModel.Text.Trim().Length==0){Say("Indica el modelo de visión habilitado en tu proveedor.");return;}Stop();visionApiPending=true;visionRevision++;Send("VISION_API|"+(visionEngine.SelectedIndex==2?"gemini":"compatible")+"|"+B64(visionEndpoint.Text.Trim())+"|"+B64(visionModel.Text.Trim())+"|"+B64(visionKey.Text));Say("Consultando la API elegida…");Log("vision_api_request");}
 void ReceiveVision(string value,bool reset){try{var root=json.Deserialize<Dictionary<string,object>>(value);visionOverview=Convert.ToString(root["overview"]);visionSource=Convert.ToString(root["source"]);int selected=visionRegions.SelectedIndex;bool previousFocus=visionFocused;visionFocused=false;regions.Clear();visionRegions.Items.Clear();foreach(object item in (IEnumerable)root["regions"]){var r=(Dictionary<string,object>)item;var b=new List<double>();foreach(object v in (IEnumerable)r["box"])b.Add(Convert.ToDouble(v,CultureInfo.InvariantCulture));var region=new VisionRegion{Left=b[0],Top=b[1],Right=b[2],Bottom=b[3],Label=Convert.ToString(r["label"]),Analogy=Convert.ToString(r["analogy"]),Source=Convert.ToString(r["source"])};regions.Add(region);visionRegions.Items.Add(regions.Count+". "+(visionInterpretations.Checked?region.Label:"Región geométrica"));}if(regions.Count>0)visionRegions.SelectedIndex=Math.Max(0,Math.Min(selected,regions.Count-1));if(!reset)visionFocused=previousFocus;if(reset){visionApiPending=false;canvas.ImageCrop=new RectangleF(0,0,1,1);visionFocused=false;}string report=(visionInterpretations.Checked?visionSource+". Interpretación aproximada: "+visionOverview+" ":"")+regions.Count+" regiones explorables.";Say(report);if(reset&&!smoke&&Form.ActiveForm==this)Speak(report);}catch{Say("La descripción recibida no tiene un formato válido.");}}
 void RefreshVisionLabels(){bool previousFocus=visionFocused;visionFocused=false;int selected=visionRegions.SelectedIndex;visionRegions.Items.Clear();for(int i=0;i<regions.Count;i++)visionRegions.Items.Add((i+1)+". "+(visionInterpretations.Checked?regions[i].Label:"Región geométrica"));if(regions.Count>0)visionRegions.SelectedIndex=Math.Max(0,Math.Min(selected,regions.Count-1));visionFocused=previousFocus;} string VisionDescription(){int n=visionRegions.SelectedIndex;if(n<0||n>=regions.Count)return "Elige un componente.";var r=regions[n];return "Componente "+(n+1)+". En la imagen completa está "+((r.Top+r.Bottom)/2<.33?"arriba":(r.Top+r.Bottom)/2>.66?"abajo":"a media altura")+", "+((r.Left+r.Right)/2<.33?"a la izquierda":(r.Left+r.Right)/2>.66?"a la derecha":"en el centro")+". "+(visionInterpretations.Checked?r.Source+": "+r.Label+". "+(r.Analogy.Length>0?"Analogía aproximada: "+r.Analogy+". ":""):"Interpretaciones ocultas. ")+(visionFocused?"Los sonidos expresan posiciones dentro de esta región ampliada.":"La caja delimita una zona; no es la silueta del objeto.");}
 void FocusVision(int n){if(n<0||n>=regions.Count||!canvas.HasBackground){Say("Importa una imagen y elige un componente.");return;}recordTrace.Checked=false;layerSelection.SelectedIndex=0;heightDeclared.Checked=false;Stop();visionRegions.SelectedIndex=n;var r=regions[n];visionFocused=true;canvas.ImageCrop=new RectangleF((float)r.Left,(float)r.Top,(float)(r.Right-r.Left),(float)(r.Bottom-r.Top));Send("IMAGE_FOCUS|"+n);Speak("Primer plano. "+VisionDescription());canvas.Invalidate();}
 void RestoreVision(){Stop();visionFocused=false;canvas.ImageCrop=new RectangleF(0,0,1,1);Send("IMAGE_RESTORE");canvas.Invalidate();Speak("Vista general restaurada. La imagen conserva su ubicación original.");}
 void OpenVisionAt(PointF p){if(visionFocused||!canvas.HasBackground)return;using(Bitmap image=canvas.SnapshotImage()){double scale=Math.Min(568.0/image.Width,418.0/image.Height),w=image.Width*scale,h=image.Height*scale,x=(p.X-(600-w)/2)/w,y=(p.Y-(450-h)/2)/h,best=2;int selected=-1;for(int i=0;i<regions.Count;i++){var r=regions[i];double area=(r.Right-r.Left)*(r.Bottom-r.Top);if(x>=r.Left&&x<=r.Right&&y>=r.Top&&y<=r.Bottom&&area<best){selected=i;best=area;}}if(selected>=0)FocusVision(selected);else Say("No hay región delimitada aquí. Usa la lista de componentes.");}}
 void CorrectVision(){if(visionBusy){Say("Espera a que termine el reconocimiento local para corregir la captura.");return;}int n=visionRegions.SelectedIndex;if(n<0||n>=regions.Count)return;using(var dialog=new Form()){dialog.Text="Anotación para esta captura";dialog.Width=650;dialog.Height=260;var layout=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false};dialog.Controls.Add(layout);layout.Controls.Add(new Label{Text="Tu interpretación",AutoSize=true});var label=new TextBox{Text=regions[n].Label,Width=580,MaxLength=160,AccessibleName="Tu interpretación"};layout.Controls.Add(label);layout.Controls.Add(new Label{Text="Analogía opcional",AutoSize=true});var like=new TextBox{Text=regions[n].Analogy,Width=580,MaxLength=240,AccessibleName="Analogía opcional"};layout.Controls.Add(like);var save=new Button{Text="Guardar",DialogResult=DialogResult.OK};layout.Controls.Add(save);dialog.AcceptButton=save;if(dialog.ShowDialog(this)==DialogResult.OK){visionApiPending=false;Send("VISION_CORRECT|"+n+"|"+B64(label.Text)+"|"+B64(like.Text));Say("Anotación para esta captura; no modifica contornos ni entrena el modelo.");}}}
}
